const c=-4,a=[{intervals:4,points:50},{intervals:3,points:30},{intervals:2,points:15},{intervals:1,points:5}];export const SACK=-5,INTERCEPTION=-10;export function pointsForPosition(t,o){for(const n of a)if(t>=-4+o*n.intervals)return n.points;return 0}export function ladderBands(t){const o=[...a].reverse().map(e=>({from:-4+t*e.intervals,points:e.points})),n=o.map((e,r)=>({from:e.from,to:r+1<o.length?o[r+1].from:1/0,points:e.points}));return[{from:-1/0,to:n[0].from,points:0},...n]}export function bandAt(t,o){const n=ladderBands(o);return n.find(e=>t>=e.from&&t<e.to)||n[0]}export function classifyPlay({ranWithBall:t,threwTo:o,ball:n,carrierX:e,lineInterval:r,reached50:i}){if(!t&&!o)return{result:"sack",points:SACK,headline:"Sacked",detail:"Nobody got the ball away in time."};if(!t){if(!n||!n.caught)return{result:"incomplete",points:0,headline:"Incomplete",detail:"The pass fell to the turf."};if(n.team!==0)return{result:"interception",points:INTERCEPTION,headline:"Intercepted",detail:"The Crows read it and took the ball away."};const u=pointsForPosition(e,r);return{result:"catch",points:u,headline:u===50?"All the way":"Caught",detail:u===50?"Caught and carried the whole way across.":`Caught and brought down for ${u}.`}}const s=pointsForPosition(e,r);return{result:i?"run-50":"run",points:s,headline:s===50?"All the way":"Kept it",detail:s===50?"Tucked it and ran the whole way across.":`Tucked it and ran for ${s}.`}}export function endSounds(t,o=!1,n=!1){const e=t&&t.points||0,r=t&&t.result||"",i=e===50;return{whistle:i||r==="interception"||r==="sack",grunt:!o&&!n&&!i&&(r==="sack"||r==="run"||r==="catch")}}export function summarise(t){const o=t.reduce((e,r)=>e+r.points,0),n=t.reduce((e,r)=>r.points>e.points?r:e,t[0]||{points:0});return{total:o,plays:t.length,best:n?n.points:0,scored:t.filter(e=>e.points>0).length,gaveAway:t.filter(e=>e.points<0).length}}export function verdictFor(t){return t>=300?"A clinic.":t>=200?"A very good afternoon.":t>=120?"Solid work.":t>=60?"Moved the ball.":t>0?"Hard yards.":"One of those games."}export function nextStreak(t,o,{good:n=30,bad:e=0}={}){const r=Number.isFinite(t)?t:0;return o>=n?r>=0?r+1:1:o<=e?r<=0?r-1:-1:r>0?r-1:r<0?r+1:0}export function streakOver(t,o){let n=0;for(const e of t||[])n=nextStreak(n,e&&e.points||0,o);return n}export function difficultyFor(t,{run:o=3}={}){if(!(o>0)||!Number.isFinite(t))return 0;const n=t/o;return n>1?1:n<-1?-1:n}
